from typing import List

def binary_search(nums: List[int], target: int) -> int:
    """
    Searches for `target` in a sorted `nums` list. Returns the index if found, or -1 if not found.
    """
    if not nums:
        raise ValueError("List cannot be empty.")
    if not isinstance(nums, list):
        raise TypeError("`nums` must be a list.")
    if not isinstance(target, (int, float)):
        raise TypeError("`target` must be an integer or float.")
    def binary_search_helper(nums: List[int], target: int, left: int, right: int) -> int:
        if left > right:
            return -1

        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            return binary_search_helper(nums, target, mid + 1, right)
        else:
            return binary_search_helper(nums, target, left, mid - 1)

    return binary_search_helper(nums, target, 0, len(nums) - 1)

