            return convert_hundreds(thousands)
        else:
            return convert_hundreds(thousands // 1000) + " Thousand" + (" and " + convert_hundreds(thousands % 1000) if thousands % 1000 != 0 else "")

    def convert(number):
        if number < 1000:
            return convert_thousands(number)
        else:
            return convert_thousands(number // 1000) + " Thousand" + (" and " + convert_thousands(number % 1000) if number % 1000 != 0 else "")
