def string_matching(string, pattern):
    if not pattern:
        raise ValueError("Pattern cannot be empty.")
    valid_chars = set(string) | {"?", "*"}
    for char in pattern:
        if char not in valid_chars:
            raise ValueError(f"Invalid character '{char}' in pattern.")
    string_ptr = 0
    pattern_ptr = 0
    while string_ptr < len(string) and pattern_ptr < len(pattern):
        if pattern[pattern_ptr] == "?":
            string_ptr += 1
            pattern_ptr += 1
        elif pattern[pattern_ptr] == "*":
            while pattern_ptr < len(pattern) - 1 and pattern[pattern_ptr + 1] == "*":
                pattern_ptr += 1
            while string_ptr < len(string) and string[string_ptr] != pattern[pattern_ptr + 1]:
                string_ptr += 1
            pattern_ptr += 1
        else:
            if string[string_ptr] != pattern[pattern_ptr]:
                return False  # String and pattern don't match
            string_ptr += 1
            pattern_ptr += 1
    return string_ptr == len(string) and pattern_ptr == len(pattern)

