def glob_all(pattern):
    """
    Returns a list of all file paths that match the given pattern.
    """
    files = []
    dir_path, file_part = os.path.split(pattern)
    if '*' in file_part:
        start_idx, end_idx = file_part.index('*'), file_part.rindex('*')
        prefix, suffix = file_part[:start_idx], file_part[end_idx+1:]
        for file_name in os.listdir(dir_path):
