def check_brackets(string):
    """
    Checks if a given string contains matching brackets.

    Args:
        string (str): The string to check.

    Returns:
        bool: True if the string contains matching brackets, False otherwise.
    """
    brackets = {
        '(': ')',
        '[': ']',
        '{': '}',
    }
    stack = []
    for char in string:
        if char in brackets:
            stack.append(char)
        elif char in brackets.values():
            if not stack or char != brackets[stack.pop()]:
                return False
    return not stack

