def serialize_object(obj):
    obj_dict = {
        "__class__": obj.__class__.__name__,
        "__module__": obj.__module__
    }
    for attr in dir(obj):
        if attr.startswith('__'):
            continue
        value = getattr(obj, attr)
        if callable(value):
            if attr.startswith('get_') or attr.startswith('is_'):
                result = value()
            else:
                continue
        else:
            result = value
        obj_dict[attr] = result
    return json.dumps(obj_dict)

