def walk(grid, start):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])):
        return None

    path = [start]

    i = start[0]
    j = start[1]

    while True:
        if i + 1 < len(grid) and (i + 1, j) not in path:
            i += 1
        elif j + 1 < len(grid[0]) and (i, j + 1) not in path:
            j += 1
        else:
