import numpy as np

def sigmoid(x):
    return 1 / (1 + np.exp(-x))

def log_loss_gradient(X, y):
    w = np.zeros(X.shape[1])  # Initialize the weight vector
    grad_avg = np.zeros(X.shape[1])  # Initialize the gradient vector

    for i, (x_i, y_i) in enumerate(zip(X, y)):
        grad = -y_i * x_i * (1 - sigmoid(np.dot(w, x_i))) + (1 - y_i) * x_i * sigmoid(np.dot(w, x_i))
        grad_avg += grad / X.shape[0]

    return grad_avg

