def fibonacci(n):
    if n < 0:
        raise ValueError("n must be non-negative.")

    def fibonacci_helper(n, memo):
        if n in memo:
            return memo[n]
        elif n == 0 or n == 1:
            result = n
        else:
            result = fibonacci_helper(n - 1, memo) + fibonacci_helper(n - 2, memo)
        memo[n] = result
        return result

    return fibonacci_helper(n, {})

