def extract_key(d, key):
    """
    Extracts the value of a key in a nested dictionary, where keys are separated by periods.
    For example, given a dictionary `d` with keys `a.c.e` and `a.f.g`, this function should return the values of those keys.
    """
    keys = key.split('.')
    if len(keys) == 1:
        return d.get(key)
    elif len(keys) > 1:
        next_key = keys.pop(0)
        next_dict = d.get(next_key)
        if next_dict is not None:
            return extract_key(next_dict, '.'.join(keys))
        else:
            return None

