def matrix_vector_multiply_and_find_max(A, b):
    m, n = len(A), len(A[0])
    if len(b) != n:
        raise ValueError("Incompatible dimensions for matrix-vector multiplication")
    result = [0] * m
    max_value, max_index = float("-inf"), -1
    for i in range(m):
        for j in range(n):
            result[i] += A[i][j] * b[j]
        if result[i] > max_value:
            max_value = result[i]
            max_index = i
    return result, max_index

