def find_intersection(rect1, rect2):
    def intersect(a, b):
        a1, a2 = a
        b1, b2 = b
        if a1 <= b1 <= a2:
            return max(b1, a1), min(b2, a2)  # Intersection is [max(b1, a1), min(b2, a2)]
        elif b1 <= a1 <= b2:
            return max(a1, b1), min(a2, b2)  # Intersection is [max(a1, b1), min(a2, b2)]
        else:
            return None, None  # No intersection
    x_intersect = intersect((rect1[0], rect1[2]), (rect2[0], rect2[2]))
    y_intersect = intersect((rect1[1], rect1[3]), (rect2[1], rect2[3]))
