def get_max_row_probability(M):
    if M is None:
        return None

    max_row_probability = []
    for row in M:
        max_value = max(row)
        num_max_values = sum(x == max_value for x in row)
        max_row_probability.append(num_max_values / len(row))

    return max_row_probability

