def factorial(n: int) -> int:
    if n == 0:
        return 1
    elif n > 0:
        memo = [None] * (n + 1)
        memo[0] = 1
        def recursive_factorial(n: int) -> int:
            if memo[n] is None:
                memo[n] = n * recursive_factorial(n - 1)
            return memo[n]
        return recursive_factorial(n)
    else:
        raise ValueError("Factorial is not defined for negative numbers.")

def modify_keys(dictionary):
    def modify_key(key):
        return str(key) + '_'

    def traverse_dictionary(dictionary):
        modified_dictionary = {}
        for key, value in dictionary.items():
            if isinstance(value, dict):
                modified_dictionary[modify_key(key)] = traverse_dictionary(value)
            else:
                modified_dictionary[modify_key(key)] = value
        return modified_dictionary

    return traverse_dictionary(dictionary)

def camel_case_to_string_with_spaces(s: str) -> str:
    """
    Converts a camelCase string to a string with spaces.
    For example, 'camelCase' is converted to 'camel case',
    and 'camelCaseExample' is converted to 'camel case example'.
    """
    result = s[0].lower()

    for c in s[1:]:
        if c.isupper():
            result += " " + c.lower()
        else:
            result += c

    return result

def reconstruct_line(tokens):
    result = []
    for token in tokens:
        if isinstance(token, str):
            result.append(f'"{token}"')
        elif isinstance(token, int) or isinstance(token, float):
            result.append(str(token))
        else:
            result.append(token)
    return " ".join(result)

def count_reachable(graph, node, visited=None):
    if visited is None:
        visited = set()

    visited.add(node)

    for neighbor in graph[node]:
        if neighbor not in visited:
            count_reachable(graph, neighbor, visited)

    return len(visited) - 1

