def to_geojson(df):
    df = df.copy()
    df = df.dropna()
    df = df.drop_duplicates()

    features = []
    for index, row in df.iterrows():
        if pd.isnull(row['longitude']) or pd.isnull(row['latitude']):
            continue

        feature = {
            'type': 'Feature',
            'geometry': {
                'type': 'Point',
                'coordinates': [row['longitude'], row['latitude']]
            },
            'properties': {
                'name': row['name'] if pd.notnull(row['name']) else None,
                'description': row['description'] if pd.notnull(row['description']) else None
            }
        }
        features.append(feature)

    geojson = {
        'type': 'FeatureCollection',
        'features': features
    }

    return geojson

