def is_within_tolerance(a, b, tol, tol_type):
    within_tolerance = False
    if tol_type == "relative":
        relative_diff = abs(a - b) / b  # Relative difference
        within_tolerance = relative_diff <= tol
    elif tol_type == "absolute":
        absolute_diff = abs(a - b)
        within_tolerance = absolute_diff <= tol
    return within_tolerance

