def median_sort(numbers):
    sorted_numbers = sorted(numbers)
    num_elements = len(sorted_numbers)

    if num_elements % 2 == 1:
        median = sorted_numbers[num_elements // 2]
    else:
        median = (sorted_numbers[num_elements // 2 - 1] + sorted_numbers[num_elements // 2]) / 2

    return median, sorted_numbers

