def find_value_in_dict(dictionary, key):
    """
    Find the value associated with a given key in a dictionary,
    handling nested dictionaries and lists.
    """
    if key in dictionary:
        return dictionary[key]

    for value in dictionary.values():
        if isinstance(value, dict):
            result = find_value_in_dict(value, key)
            if result is not None:
                return result
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, dict):
                    result = find_value_in_dict(item, key)
                    if result is not None:
                        return result

    return None

