        elif isinstance(value, list):
            return sum(sum_with_lists_helper(item) for item in value)
        else:
            raise TypeError(
                "Unexpected value type: {}".format(type(value).__name__)
            )
    return sum(sum_with_lists_helper(value) for value in values)

import re

def identify_elements(formula):
    element_counts = {}
    element_pattern = re.compile(r"(\D+)(\d*)")
    for element, num_atoms in element_pattern.findall(formula):
        num_atoms = int(num_atoms) if num_atoms else 1
        element_counts[element] = element_counts.get(element, 0) + num_atoms
    return element_counts

