def bucketize(value, bucket_size):
    if value < 0:
        return -1
    max_age = 120  # Adjust as needed for your use case
    num_buckets = max_age // bucket_size + 1
    bucket_index = int(value / bucket_size)
    remainder = value % bucket_size
    if remainder < bucket_size // 2:
        bucket_index -= 1
    else:
        bucket_index += 1
    if bucket_index < 0:
        bucket_index = 0
    elif bucket_index >= num_buckets:
        bucket_index = num_buckets - 1

    return bucket_index

