def replace_string_key_value_pairs(input_string: str, key_value_pairs: dict) -> str:
    try:
        if not input_string or not key_value_pairs:
            raise ValueError('Invalid input')

        output_string = input_string
        for key, value in key_value_pairs.items():
            index = output_string.find(key)
            while index != -1:
                output_string = output_string[:index] + value + output_string[index + len(key):]
                index = output_string.find(key, index + len(value))

        return output_string
    except Exception as e:
        print(f'Error: {e}')
        return input_string

def validate_input_data(expected_type):
    def decorator(func):
        def inner(data):
            def validate(data):
                for var_name, var_value in data:
                    if not isinstance(var_value, expected_type):
                        raise TypeError(f"Variable '{var_name}' is not of type {expected_type}")
            try:
                validate(data)
                return func(data)
            except TypeError as e:
                raise Exception(f"Invalid input data: {e}")
        return inner
    return decorator

