import base64

def bytes_to_str(bytes_obj: bytes) -> str:
    """Converts a bytes object to a string."""
    return bytes_obj.decode('utf-8')

def base64_encode(raw_str: str) -> str:
    """Encodes a raw string to Base64 format."""
    bytes_obj = raw_str.encode('utf-8')
    encoded_bytes = base64.b64encode(bytes_obj)
    encoded_str = bytes_to_str(encoded_bytes)
    return encoded_str

