class ObjectCreationError(Exception):
    """Exception raised when there is an error in object creation.

    Attributes:
        reason (str): The reason for the error.
        object_type (str): The object type that couldn't be created.
        spec (dict): The specification of the object that couldn't be created.
    """
    def __init__(self, reason, object_type, spec):
        self.reason = reason
        self.object_type = object_type
        self.spec = spec

    def fix(self):
        """Attempt to fix the issue and re-create the object."""

class CannotFixError(Exception):
    """Exception raised when fixing an issue in object creation fails."""
    pass

def create_objects_from_specs(specs, class_map):
    if not specs:
        raise ValueError("No specifications provided.")
    if not class_map:
        raise ValueError("No class mapping provided.")

    objects = []

    for spec in specs:
        object_type = spec.get("type")
        if object_type not in class_map:
            raise ObjectCreationError(
                reason=f"Invalid object type: {object_type}",
                object_type=object_type,
                spec=spec,
            )

        try:
            cls = class_map[object_type]
            obj = cls(**spec["args"])
            objects.append(obj)
        except Exception as e:
            try:
                e.fix()
                obj = cls(**spec["args"])
                objects.append(obj)
            except CannotFixError:
                raise ObjectCreationError(
                    reason=f"Failed to create object: {e}",
                    object_type=object_type,
                    spec=spec,
                )

    return objects

