def zipped_sum(list_1, list_2):
    shorter_length = min(len(list_1), len(list_2))
    longer_length = max(len(list_1), len(list_2))
    if len(list_1) < len(list_2):
        list_1 = list_1 + [0] * (longer_length - shorter_length)
    else:
        list_2 = list_2 + [0] * (longer_length - shorter_length)
    summed_list = []
    for a, b in zip(list_1, list_2):
        summed_list.append(a + b)

    return summed_list

