def calculate_bias(y_pred, y_true):
    tp = np.sum(np.logical_and(y_pred, y_true))
    fp = np.sum(np.logical_and(np.logical_not(y_pred), y_true))
    tn = np.sum(np.logical_and(np.logical_not(y_pred), np.logical_not(y_true)))
    fn = np.sum(np.logical_and(y_pred, np.logical_not(y_true)))
    return (tp + tn) / (tp + fp + tn + fn)

