def relative_path_to_absolute_path(relative_path: str) -> str:
    """
    Converts a given relative path to an absolute path. This function handles different
    platforms by using the path separator for the current platform. It also handles
    edge cases such as an empty string input or a relative path that contains a leading slash.
    """
    if not relative_path:
        return os.getcwd()

    if relative_path[0] == os.path.sep:
        return os.path.abspath(relative_path)

    current_directory = os.getcwd()
    return os.path.abspath(os.path.join(current_directory, relative_path))

import heapq

def find_max_salary(data, k):
    heap = []
    for employee in data:
        if len(heap) < k:
            heapq.heappush(heap, employee[1])
        elif employee[1] > heap[0]:
