def calculator(tokens: List[str]) -> int:
    """
    Simulates a simple calculator with four operations: addition, subtraction,
    multiplication, and division.
    """
    stack = []
    for token in tokens:
        if token == "+":
            b, a = stack.pop(), stack.pop()
            stack.append(a + b)
        elif token == "-":
            b, a = stack.pop(), stack.pop()
            stack.append(a - b)
        elif token == "*":
            b, a = stack.pop(), stack.pop()
            stack.append(a * b)
        elif token == "/":
            b, a = stack.pop(), stack.pop()
            stack.append(a / b)
        else:
            stack.append(int(token))
    return stack[-1]

