    prime[0] = False
    prime[1] = False

    for i in range(2, int(math.sqrt(n)) + 1):
        if prime[i]:
            for j in range(i * i, n + 1, i):
                prime[j] = False

    return prime


def gcd_of_prime_factors(n):
    prime = sieve_of_eratosthenes(n)

    prime_factors = []
    for i in range(2, n + 1):
        if prime[i] and n % i == 0:
            prime_factors.append(i)

    max_prime_factor = 1
    for i in range(len(prime_factors)):
        for j in range(i + 1, len(prime_factors)):
            if prime_factors[j] % prime_factors[i] == 0:
                max_prime_factor = max(max_prime_factor, prime_factors[j] // prime_factors[i])
            else:
                max_prime_factor = max(max_prime_factor, 1)

    return max_prime_factor

