    for segment in parsed_url.path.split('/'):
        if not segment:
            return f"Invalid segment: '{segment}'. Path segments must be non-empty."
    if parsed_url.query:
        for pair in parsed_url.query.split('&'):
            if '=' not in pair:
                return f"Invalid query string: '{pair}'. Query string pairs must be in the form 'key=value'."
            key, value = pair.split('=')
            if not key or not value:
                return f"Invalid query string pair: '{pair}'. Keys and values must be non-empty."
    components = []
    if parsed_url.scheme:
        components.append(parsed_url.scheme)
    if parsed_url.netloc:
        components.append(parsed_url.netloc)
    if parsed_url.path:
        components.append(parsed_url.path)
