import importlib

def dynamic_import(module_name):
    """
    Loads a module dynamically based on a string input. If an error occurs during import, 
    handles it gracefully and retries after invalidating the cache. If the error persists, 
    raises an exception.
    """
    module = None
    retries = 3  # Maximum number of retries

    while retries > 0:
        try:
            module = importlib.import_module(module_name)
        except ModuleNotFoundError:
            importlib.invalidate_caches()
            retries -= 1
        else:
            break

    if module is None:
        raise ImportError("Failed to import module after {} retries".format(3 - retries))

    return module

def binomial(n: int, k: int) -> int:
    """
    Returns the number of unique combinations of `k` numbers out of `n`.
    """
    combinations = [[0 for j in range(k + 1)] for i in range(n + 1)]
    for i in range(n + 1):
        combinations[i][0] = 1
    for i in range(1, n + 1):
        for j in range(1, min(i, k) + 1):
            combinations[i][j] = combinations[i - 1][j - 1] + combinations[i - 1][j]

    return combinations[n][k]

