def ternary_search(array, target):
    left = 0
    right = len(array) - 1

    while left <= right:
        mid_1 = left + (right - left) // 3
        mid_2 = right - (right - left) // 3

        if array[mid_1] == target:
            return mid_1
        elif array[mid_2] == target:
            return mid_2
        elif target < array[mid_1]:
            right = mid_1 - 1
