import os

def dir_name(f):
    def wrapper(*args, **kwargs):
        new_dir = f(*args, **kwargs)
        current_dir = os.getcwd()
        dir_name = os.path.split(current_dir)[-1]

        if dir_name != new_dir:
            os.rename(current_dir, os.path.join(os.path.dirname(current_dir), new_dir))

        return new_dir

    return wrapper

