import itertools

def get_board_states(board_size, check_program_correctness):
    board_states = list(itertools.product([0, 1], repeat=board_size * board_size))

    if check_program_correctness:
        for board_state in board_states:
            if not verify_minesweeper_rule(board_state, board_size):
                raise AssertionError("Minesweeper rule violated for board state: ", board_state)

    return board_states

def verify_minesweeper_rule(board_state, board_size):
    if any(square not in [0, 1] for square in board_state):
        return False
    for i in range(board_size):
        if sum(board_state[i * board_size:(i + 1) * board_size]) > 1:
            return False
        if sum(board_state[i::board_size]) > 1:
            return False
        for j in range(board_size):
            if board_state[i * board_size + j] == 1:
                continue
            mine_count = 0
            for k in range(i - 1, i + 2):
                for l in range(j - 1, j + 2):
                    if 0 <= k < board_size and 0 <= l < board_size:
                        if board_state[k * board_size + l] == 1:
                            mine_count += 1

            if mine_count > 1:
                return False

    return True

