class Course:
    def __init__(self, name, prerequisites):
        self.name = name
        self.prerequisites = prerequisites

def topological_sort(courses):
    prerequisites_dict = defaultdict(list)
    for course in courses:
        if course.prerequisites:
            for prerequisite in course.prerequisites:
                prerequisites_dict[course.name].append(prerequisite)
    sorted_courses = []
    visited = set()
    def dfs(course_name):
        if course_name in visited:
            return
        visited.add(course_name)
        for prerequisite in prerequisites_dict[course_name]:
            dfs(prerequisite)
        sorted_courses.append(course_name)

    for course in courses:
        dfs(course.name)

    return sorted_courses

