def factor(monomials):
    terms = {term.coefficient: term for term in monomials}
    polynomials = []
    for i, term in enumerate(monomials):
        for j in range(i+1, len(monomials)):
            if term.exponent == monomials[j].exponent:
                polynomials.append((term, monomials[j]))
    rational_functions = []
    for i, term in enumerate(monomials):
        for j in range(i+1, len(monomials)):
            if term.exponent - monomials[j].exponent == 1:
                rational_functions.append((term, monomials[j]))
    cancel_terms = []
    for i, term in enumerate(monomials):
        for j in range(i+1, len(monomials)):
