def k_subsequences(sequence, k):
    if not sequence or k <= 0:
        return []

    subsequences = []

    def backtrack(current_subsequence, start):
        if len(current_subsequence) == k:
            subsequences.append(current_subsequence[:])
            return

        for i in range(start, len(sequence)):
            if sequence[i] not in current_subsequence:
                current_subsequence.append(sequence[i])
                backtrack(current_subsequence, i + 1)
                current_subsequence.pop()

    backtrack([], 0)
    return subsequences

