def create_random_socket(socket_type, ip_address=None, port_range=(1024, 65535)):
    """Creates a socket with a random port and optional IP address"""
    if socket_type not in (socket.SOCK_STREAM, socket.SOCK_DGRAM):
        raise ValueError("Invalid socket type")
    port = random.randint(*port_range)
    if not ip_address:
