def product_except_nth(numbers):
    """
    Returns a list of integers, where the nth element is the product of all integers in the list except the nth element.
    The function should be optimized to run in linear time and use constant space.
    """
    if not numbers:
        raise ValueError('Input list cannot be empty')

    product = 1
    for n in numbers:
        if n == 0:
            raise ValueError('Input list cannot contain zeros, as the product of all integers except one would be 0')
        product *= n

    result = []
    for i, n in enumerate(numbers):
        result.append(product // n)

    return result

