def median_of_divisors(a):
    divisors = []
    for value in a:
        for divisor in range(1, value + 1):
            if value % divisor == 0:
                divisors.append(divisor)

    divisors.sort()
    length = len(divisors)
    if length % 2 == 0:
        sum_of_values = sum(a)
        median = divisors[(length // 2) - 1] + (divisors[length // 2] - divisors[(length // 2) - 1]) // 2
    else:
        median = divisors[length // 2]
    median = int(median // 1)

    return median

