def wrap_list(lst, n):
    if n <= 0:
        raise ValueError("n must be a positive integer")
    wrapped_list = []
    while len(lst) > n:
        sublist = lst[:n]
        wrapped_list.append(sublist)
        lst = lst[n:]
    if len(lst) < n:
        lst += [None] * (n - len(lst))
    wrapped_list.append(lst)

