def is_symmetric(root: TreeNode) -> bool:
    if root is None:
        return True

    def mirror_image(node: TreeNode) -> TreeNode:
        if node is None:
            return None
        return TreeNode(node.val, mirror_image(node.right), mirror_image(node.left))

    def compare_trees(tree1: TreeNode, tree2: TreeNode) -> bool:
        if tree1 is None and tree2 is None:
            return True
        if tree1 is not None and tree2 is not None:
            return tree1.val == tree2.val and compare_trees(tree1.left, tree2.left) and compare_trees(tree1.right, tree2.right)
        return False

    return compare_trees(root, mirror_image(root))

