def edit_distance(s1, s2):
    if len(s1) == 0:
        return len(s2)
    if len(s2) == 0:
        return len(s1)

    memo = [[None for j in range(len(s2) + 1)] for i in range(len(s1) + 1)]

    def edit_distance_recursive(s1, s2, i, j):
        if i == 0:
            return j
        if j == 0:
            return i
        if memo[i][j] is not None:
            return memo[i][j]
        if s1[i - 1] == s2[j - 1]:
            memo[i][j] = edit_distance_recursive(s1, s2, i - 1, j - 1)
        else:
            memo[i][j] = 1 + min(
                edit_distance_recursive(s1, s2, i, j - 1),  # insertion
                edit_distance_recursive(s1, s2, i - 1, j),  # deletion
                edit_distance_recursive(s1, s2, i - 1, j - 1)  # substitution
            )
        return memo[i][j]

    return edit_distance_recursive(s1, s2, len(s1), len(s2))

