import numpy as np

def convolve(image, kernel, padding='CONSTANT'):
    m, n = image.shape
    k, l = kernel.shape
    if padding == 'CONSTANT':
        padded_image = np.pad(image, ((k // 2, k // 2), (l // 2, l // 2)), constant_values=0)
    elif padding == 'REFLECT':
        padded_image = np.pad(image, ((k // 2, k // 2), (l // 2, l // 2)), mode='reflect')
    elif padding == 'WRAP':
        padded_image = np.pad(image, ((k // 2, k // 2), (l // 2, l // 2)), mode='wrap')
    else:
        raise ValueError("Invalid padding mode: must be 'CONSTANT', 'REFLECT', or 'WRAP'.")
    output = np.zeros((m, n))
    for i in range(k // 2, m + k // 2):
        for j in range(l // 2, n + l // 2):
            output[i - k // 2, j - l // 2] = np.sum(padded_image[i - k // 2:i + k // 2 + 1, j - l // 2:j + l // 2 + 1] * kernel)
    return output

