def traverse_level(root):
    if not root:
        return []

    queue = [(root, 0)]
    levels = []

    while queue:
        node, depth = queue.pop(0)

        if len(levels) == depth:
            levels.append([])

        levels[depth].append(node.value)

        if node.left:
            queue.append((node.left, depth + 1))
        if node.right:
            queue.append((node.right, depth + 1))

    return levels

