        return "{" + ", ".join([f'"{key}": {json_encode_nested(value)}' for key, value in obj.items()]) + "}"
    elif isinstance(obj, list):
        return "[" + ", ".join([json_encode_nested(item) for item in obj]) + "]"
    elif isinstance(obj, bool):
        return str(obj).lower()
    elif isinstance(obj, str):
        return f'"{obj}"'
    else:
