def prime_sieve(n):
    prime_factors = []
    for i in range(2, n + 1):
        is_prime = True
        for j in range(2, int(i ** 0.5) + 1):
            if i % j == 0:
                is_prime = False
                break
        if is_prime:
            prime_factors.append(i)
    return prime_factors

def factor_into_primes(n):
    prime_factors = prime_sieve(n)
    factors = []
    for prime in prime_factors:
        while n % prime == 0:
            factors.append(prime)
            n //= prime
    return factors

