def compute_md5_checksums(file_path):
    md5_checksums = {}
    with open(file_path, 'r') as file:
        reader = csv.reader(file)
        for url in reader:
            try:
                md5_checksum = hashlib.md5(url.encode('utf-8')).hexdigest()
                if md5_checksum not in md5_checksums:
                    md5_checksums[md5_checksum] = url
            except Exception as e:
                print(f"Error computing MD5 checksum for {url}: {e}")

    return md5_checksums

