def get_event_stats(event_log):
    stats = {}
    for event in event_log:
        date_time = datetime.datetime.strptime(event["time"], "%Y-%m-%d %H:%M:%S")
        stats["total_events"] = stats.get("total_events", 0) + 1
        if not "start_date" in stats or date_time < stats["start_date"]:
            stats["start_date"] = date_time
        if not "end_date" in stats or date_time > stats["end_date"]:
            stats["end_date"] = date_time
    if "start_date" in stats and "end_date" in stats:
        stats["active_days"] = (stats["end_date"] - stats["start_date"]).days + 1
    if "active_days" in stats:
        stats["avg_events_per_day"] = stats["total_events"] / stats["active_days"]

    return stats

