def is_valid_schema(json_object):
    """
    Check whether a JSON object is a valid JSON schema.

    Args:
        json_object (dict): JSON object to check.

    Returns:
        bool: True if the JSON object is a valid schema, False otherwise.
    """
    if not isinstance(json_object, dict):
        return False

    if "type" not in json_object or json_object["type"] != "object":
        return False

    if "properties" not in json_object or not isinstance(json_object["properties"], dict):
        return False

    required_fields = {"firstName", "lastName", "age", "email"}
    schema_fields = set(json_object["properties"].keys())
    return required_fields.issubset(schema_fields)

