    opposite_map = {
        "north": "south",
        "south": "north",
        "east": "west",
        "west": "east"
    }
    if direction in opposite_map:
        return opposite_map[direction]
    else:
        return direction

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

def count_primes_between(n: int, m: int) -> int:
    primes = [prime for prime in range(2, m + 1) if is_prime(prime)]
    filtered_primes = [prime for prime in primes if prime >= n and prime <= m]
    return len(filtered_primes)

