def downsample_time_series(ts, new_times=None):
    max_time = max(max(t[0] for t in time_series) for time_series in ts)
    if new_times is None:
        new_times = range(max_time)
    downsampled_ts = []
    for time_series in ts:
        downsampled_ts.append([(t, v) for t, v in time_series if t in new_times])

    return downsampled_ts

