def convert_to_efficient_type(float_values):
    min_value = min(float_values)
    max_value = max(float_values)
    unique_values = len(set(float_values))

    if max_value - min_value <= 255:
        data_type = 'uint8'
    elif max_value - min_value <= 65535:
        data_type = 'uint16'
    else:
        data_type = 'float'

    if unique_values / len(float_values) >= 0.95:
        data_type += '_unique'

    return data_type

