import hashlib

def compute_sha256_digest(file_path):
    sha256_hash = hashlib.sha256()
    with open(file_path, 'rb') as f:
        while True:
            chunk = f.read(4096)
            if not chunk:
                break
            sha256_hash.update(chunk)
    return sha256_hash.hexdigest()

def compare_boolean_tuples(tuple1, tuple2):
    if len(tuple1) != len(tuple2):
        return (False,) * max(len(tuple1), len(tuple2))

    result = []
    for e1, e2 in zip(tuple1, tuple2):
        if e1 is e2:
            result.append(True)
        elif e1 is True and e2 is False:
            result.append(False)
        elif e1 is False and e2 is True:
            result.append(False)
        else:
            return (False,) * len(tuple1)

    return tuple(result)

