def diff_sq_sum(n):
    if n < 1:
        raise ValueError("n must be a positive integer.")

    sum_of_nums = 0
    sum_of_squares = 0

    for i in range(1, n + 1):
        sum_of_nums += i
        sum_of_squares += i * i

    return sum_of_nums ** 2 - sum_of_squares

import re

def match_regexp(string, regexps):
    """
    Returns True if any of the regular expressions in `regexps` match `string`,
    False otherwise. Uses a case-insensitive matching approach.
    """
    for regexp in regexps:
        if re.match(regexp, string, re.IGNORECASE):
            return True
    return False

