def pca_normalize(data: torch.Tensor) -> torch.Tensor:
    data_type = data.dtype
    if data_type == torch.float32:
        return F.normalize(data, p=2)
    elif data_type == torch.int8:
        return data / 255
    else:
        raise ValueError("Unsupported data type")

def find_subsets(nums, target):
    subsets = []

    def backtrack(nums, subset, idx, target):
        if target == 0:
            subsets.append(subset.copy())
            return

        for i in range(idx, len(nums)):
            if target - nums[i] >= 0:
                subset.append(nums[i])
                backtrack(nums, subset, i + 1, target - nums[i])
                subset.pop()

    backtrack(nums, [], 0, target)
    return subsets

