def bitstring_to_hex(bitstring):
    if not bitstring.isnumeric() or not set(bitstring) <= {'0', '1'}:
        raise ValueError("Bitstring must contain only '0' and '1' characters")
    groups = [bitstring[i:i+4] for i in range(0, len(bitstring), 4)]
    hex_digits = [hex(int(group, 2))[2:] for group in groups]
    return ''.join(hex_digits).upper()

