def fibonacci_tail_recursion(n):
    """
    Compute the n-th Fibonacci number using tail recursion.

    Args:
        n (int): The index of the Fibonacci number to compute.

    Returns:
        int: The n-th Fibonacci number.

    Precondition:
        n must be a non-negative integer.

    Raises:
        ValueError: If n is negative.
    """
    if n < 0:
        raise ValueError("n must be a non-negative integer.")

    def helper(n, prev=0, curr=1):
        if n == 0:
            return prev
        if n == 1:
            return curr
        return helper(n - 1, curr, prev + curr)

    return helper(n)

from collections import deque

def bfs_path(graph, start, goal):
    if start == goal:
        return []

    visited = set()  # Set to keep track of visited vertices
    queue = deque([start])  # Queue to store vertices to be explored

    while queue:
        vertex = queue.popleft()

        if vertex == goal:
            return construct_path(vertex)

        visited.add(vertex)

        for neighbor in graph.get_neighbors(vertex):
            if neighbor not in visited:
                queue.append(neighbor)

    return None

