def find_elements(input_list, threshold):
    input_list.sort()
    result = []

    for i in range(len(input_list) - 1):
        current = input_list[i]
        next_element = input_list[i + 1]

        if current >= threshold and current not in result:
            result.append(current)

        if next_element >= threshold and next_element not in result:
            result.append(next_element)

    return result

