def attribute_access(obj, path, default):
    path_parts = path.split(".")

    for part in path_parts:
        if isinstance(obj, dict):
            try:
                obj = obj[part]
            except KeyError:
                return default
        else:
            try:
                obj = getattr(obj, part)
            except AttributeError:
                return default

    return obj

import random

def get_random_color_from_list(version=None):
    """
    Selects a random color from a list of colors.

    Args:
        version (int, optional): The version of the color to use. Defaults to None, which uses RGB format.

    Returns:
        str: The selected color.
    """
    if version is None or version == 1:
        colors = ["red", "green", "blue"]
    elif version == 2:
        colors = ["#ff0000", "#00ff00", "#0000ff"]
    elif version == 3:
        colors = ["hsl(0, 100%, 50%)", "hsl(120, 100%, 50%)", "hsl(240, 100%, 50%)"]
    else:
        raise ValueError("Invalid version specified.")

    return random.choice(colors)

