def contour_to_centroid(contour):
    total_mass = 0
    x_mass = 0
    y_mass = 0

    for i, row in enumerate(contour):
        for j, value in enumerate(row):
            if value == 1:
                total_mass += 1
                x_mass += j
                y_mass += i

    if total_mass > 0:
        return x_mass / total_mass, y_mass / total_mass
    else:
        return None

