from functools import wraps

def parameter_registry(registry=None):
    """
    Decorator that registers function calls with parameters to a registry. The
    decorator takes an optional argument `registry` that is a dictionary where
    the key is the function name and the value is a list of parameter values. If
    the optional argument is not provided, use an internal dictionary.
    """
    if registry is None:
        registry = {}

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            func_name = func.__name__
            if func_name not in registry:
                registry[func_name] = []
            registry[func_name].append((args, kwargs))
            return func(*args, **kwargs)
        wrapper.registry = registry
        return wrapper

    return decorator

