import math

def Shape(shape_type):
    """Factory function to create shapes"""

    def Circle(radius):
        """Circle shape"""
        area = math.pi * radius ** 2
        perimeter = 2 * math.pi * radius
        return {
            "area": lambda: area,
            "perimeter": lambda: perimeter,
            "type": "circle"
        }

    def Rectangle(width, height):
        """Rectangle shape"""
        area = width * height
        perimeter = 2 * (width + height)
        return {
            "area": lambda: area,
            "perimeter": lambda: perimeter,
            "type": "rectangle"
        }

    def Triangle(side_a, side_b, side_c):
        """Triangle shape"""
        s = (side_a + side_b + side_c) / 2
        area = math.sqrt(s * (s - side_a) * (s - side_b) * (s - side_c))
        perimeter = side_a + side_b + side_c
        return {
            "area": lambda: area,
            "perimeter": lambda: perimeter,
            "type": "triangle"
        }

    shape_creators = {
        "circle": Circle,
        "rectangle": Rectangle,
        "triangle": Triangle
    }
    return shape_creators[shape_type]

