from collections import deque

def assign_ports(ports, topology):
    assigned_switches = {}
    port_to_switch = {port: None for port in ports}
    graph = {switch: [] for switch in set(sum(topology, []))}
    for edge in topology:
        graph[edge[0]].append(edge[1])
        graph[edge[1]].append(edge[0])
    queue = deque(ports)
    visited = set()
    while queue:
        port = queue.popleft()
        queue_bfs = deque([port])
        visited_bfs = set()
        while queue_bfs:
            current_port = queue_bfs.popleft()
            visited_bfs.add(current_port)
            if current_port in port_to_switch:
                port_to_switch[current_port] = current_port
                break
            for neighbor in graph[current_port]:
                if neighbor not in visited_bfs:
                    queue_bfs.append(neighbor)
        assigned_switches[port] = port_to_switch[current_port]
        visited.add(port_to_switch[current_port])
        queue = deque(p for p in queue if port_to_switch[p] not in visited)

    return assigned_switches

