T = TypeVar('T')

def frequency_of(element: T, xs: Optional[List[T]]) -> int:
    """
    Returns the frequency of an element in a list, where the element can be a simple type
    such as `str` or `int`, or a list type.
    """
    if xs is None:
        return 0
    count = 0
    for x in xs:
        if type(x) == list:
            count += frequency_of(element, x)
        else:
            if x == element:
                count += 1
    return count

