def find_in_sorted_list(sorted_list, target):
    def binary_search(start, end):
        if start >= end:
            return None

        mid = (start + end) // 2
        if target < sorted_list[mid][0]:
            return binary_search(start, mid)
        elif target > sorted_list[mid][0]:
            return binary_search(mid + 1, end)
        else:
            if sorted_list[mid][1]:
                return mid
            else:
                return binary_search(mid + 1, end)

    return binary_search(0, len(sorted_list))

