import numpy as np

def rmse(actual, forecast):
    if len(actual) != len(forecast):
        raise ValueError("The actual and forecast arrays must have the same length.")
    actual = np.ravel(actual)
    forecast = np.ravel(forecast)
    diff = actual - forecast
    squared_diff = diff ** 2
    mean = np.mean(squared_diff)
    return np.sqrt(mean)

def batch_process(items, batch_size, process_batch):
    num_batches = -(-len(items) // batch_size)  # Round up to the nearest integer
    results = []
    for i in range(num_batches):
        start = i * batch_size
        end = min(len(items), start + batch_size)
        batch = items[start:end]
        result = process_batch(batch)
        results.append(result)
    return results

