from typing import Dict, List

def has_eulerian_tour(graph: Dict[int, List[int]]) -> bool:
    """
    Determines whether a directed graph has an Eulerian tour. A Eulerian tour is a
    closed path that visits every edge of the graph exactly once.
    """
    out_degrees = {vertex: 0 for vertex in graph}
    in_degrees = {vertex: 0 for vertex in graph}

    for vertex, neighbors in graph.items():
        out_degrees[vertex] = len(neighbors)
        for neighbor in neighbors:
            if neighbor not in in_degrees:
                in_degrees[neighbor] = 0
            in_degrees[neighbor] += 1

    odd_vertices = 0
    for vertex in graph:
        if out_degrees[vertex] != in_degrees[vertex]:
            odd_vertices += 1

    return odd_vertices == 2

