def mean_and_std_along_axis(tensor: torch.Tensor, axis: int) -> torch.Tensor:
    if not isinstance(tensor, torch.Tensor):
        raise ValueError("Input tensor must be a torch.Tensor.")
    if not torch.is_floating_point(tensor):
        raise ValueError("Input tensor must be floating-point.")
    if not isinstance(axis, int):
        raise ValueError("Axis must be an integer.")
    if axis < 0 or axis >= len(tensor.shape):
        raise ValueError("Axis out of range.")
    if tensor.numel() < 2:
        raise ValueError("Input tensor must have at least two elements.")
    mean = tensor.mean(dim=axis)
    std = tensor.std(dim=axis)
    return mean, std

