def hash_to_hex_string(input_bytes, hash_function):
    """
    Returns the hexadecimal representation of a hash of the given input.

    Args:
        input_bytes (bytes): Input data to be hashed.
        hash_function (str): Hashing function to use, one of 'sha1', 'sha256', 'sha384', 'sha512', or 'blake2b'.

    Returns:
        str: Hexadecimal representation of the hashed input.
    """
    hash_functions = ['sha1', 'sha256', 'sha384', 'sha512', 'blake2b']
    if hash_function not in hash_functions:
        raise ValueError("Invalid hash_function, must be one of 'sha1', 'sha256', 'sha384', 'sha512', or 'blake2b'.")
    if hash_function == 'sha1':
        hasher = hashlib.sha1()
    elif hash_function == 'sha256':
        hasher = hashlib.sha256()
    elif hash_function == 'sha384':
        hasher = hashlib.sha384()
    elif hash_function == 'sha512':
        hasher = hashlib.sha512()
    else:
        hasher = hashlib.blake2b()

    hasher.update(input_bytes)
    return hasher.hexdigest()

