import numpy as np

def tensor_reshape(tensor, shape):
    if not isinstance(shape, tuple):
        raise ValueError("Target shape must be a tuple of integers")

    num_dimensions = len(shape)
    if num_dimensions != tensor.ndim:
        raise ValueError(f"Number of dimensions in target shape ({num_dimensions}) does not match number of dimensions in tensor ({tensor.ndim})")

    num_elements = np.prod(shape)
    if num_elements != tensor.size:
        raise ValueError(f"Total number of elements in target shape ({num_elements}) does not match number of elements in tensor ({tensor.size})")

    if Ellipsis in shape:
        ellipsis_idx = shape.index(Ellipsis)
        if ellipsis_idx != 0 and ellipsis_idx != num_dimensions - 1:
            raise ValueError("Ellipsis must be the first or last element in the target shape tuple")

        if ellipsis_idx == 0:
            inferred_dimension = np.prod(shape[1:]) // tensor.size
        else:
            inferred_dimension = tensor.size // np.prod(shape[:-1])

        shape = shape[:ellipsis_idx] + (inferred_dimension,) + shape[ellipsis_idx+1:]
    return tensor.reshape(shape)

