        raise TypeError("Input must be a dictionary")

    if not decision_tree or not isinstance(decision_tree, dict):
        raise TypeError("Decision tree must be a non-empty dictionary")

    root_node = next(iter(decision_tree))

    if root_node not in input:
        return default

    feature_value = input[root_node]

    if feature_value not in decision_tree[root_node]:
        return default

    child_node = decision_tree[root_node][feature_value]

