import inspect

def create_update_function(obj):
    def update_function(**kwargs):
        signature = inspect.signature(getattr(obj, 'update'))
        object_type = 'class' if inspect.isclass(obj) else 'instance'
        if object_type == 'class':
            obj.update(**kwargs)
        elif object_type == 'instance':
            obj.__class__.update(obj, **kwargs)
        else:
            raise TypeError(f"Object type '{object_type}' is not supported")
        args = signature.parameters.get('args')
        if args is not None:
            for arg in args:
                setattr(obj, arg, kwargs.get(arg))

    return update_function

