        return fibonacci_element(fib_seq, n - 1) + fibonacci_element(fib_seq, n - 2)

def smart_multiply(x, y, opt=False):
    """
    Returns the product of x and y.
    If opt is True, returns the product raised to the power of 2.
    """
    if opt is True:
        return (x * y) ** 2
    else:
        return x * y

