def nth_fibonacci(n: int) -> int:
    if n < 0:
        raise ValueError("Invalid input: n should be a positive integer.")
    fib_1 = 0
    fib_2 = 1
    for _ in range(2, n + 1):
        fib_next = fib_1 + fib_2
        fib_1 = fib_2
        fib_2 = fib_next

    return fib_2

def set_check(A, B):
    set_A = set(A)
    set_B = set(B)

    subset = set_A.issubset(set_B)
    superset = set_B.issuperset(set_A)

    return (subset, superset)

import re

def parse_line(line):
    number_pattern = r'(?P<number>\d+(\.\d+)?)'
    string_pattern = r'(?P<string>"[^"]+"|\'[^\']+\')'
    word_pattern = r'(?P<word>\w+)'
    regex_pattern = fr'(?:{number_pattern}|{string_pattern}|{word_pattern})'
    matches = re.findall(regex_pattern, line)

    tokens = []
    for match in matches:
        if match[0] is not None:
            tokens.append(float(match[0]))
        elif match[1] is not None:
            tokens.append(match[1][1:-1])
        else:
            tokens.append(match[2])

    return tokens

