def find_all_paths(edges):
    graph = {}
    for edge in edges:
        source, target = edge
        if source not in graph:
            graph[source] = []
        graph[source].append(target)
    result = []

    def dfs(start, path):
        if start not in graph:
            result.append(path)
            return
        for next_node in graph[start]:
            dfs(next_node, path + [next_node])
    if len(graph) > 0:
        dfs(list(graph.keys())[0], [list(graph.keys())[0]])

    return result

