def get_temperature_category(celsius_value: float) -> str:
    if not -273.15 <= celsius_value <= 100:
        raise ValueError('Invalid temperature')

    if celsius_value <= -10:
        return 'Cold'
    elif -10 < celsius_value < 0:
        return 'Chilly'
    elif 0 <= celsius_value < 20:
        return 'Comfortable'
    elif 20 <= celsius_value < 35:
        return 'Hot'
    else:
        return 'Extreme'

