def splice_image_data(image):
    new_image = []
    for row_idx, row in enumerate(image):
        spliced_row = row.copy()  # Make a copy to avoid modifying the original image
        if row_idx % 2 == 0:
            spliced_row.reverse()
        new_image.append(spliced_row)
    return new_image

class Matrix:
    def __init__(self, elements):
        assert all(isinstance(row, list) and len(row) > 0 for row in elements), "Invalid input for elements"
        self.elements = elements
        self.rows = len(elements)
        self.cols = len(elements[0])

    def shape(self):
        return (self.rows, self.cols)

    def scale(self, scalar):
        for i in range(self.rows):
            for j in range(self.cols):
                self.elements[i][j] *= scalar

def count_equi_leaders(array):
    equi_leaders = 0
    for i, item in enumerate(array):
        if array.count(item) > len(array) / 2 and item == max(array[:i + 1]):
            equi_leaders += 1
    return equi_leaders

