def slice_data(input, epoch_size):
    subsets = []
    current_subset = []
    for elem in input:
        current_subset.append(elem)
        if len(current_subset) == epoch_size:
            subsets.append(current_subset)
            current_subset = []
    if current_subset:
        subsets.append(current_subset)

    return subsets

